class ConditionByFormula(SwSystemconstDependentFormula):
    """
    This class represents a condition which is computed based on system constants according to the specified expression. The expected result is a considered as boolean value., , The result of the expression is interpreted as a condition. , , * "0" represents "false";  , , * a value greater than zero is considered "true"
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CONDITION-BY-FORMULA'
        self._node = etree.Element('CONDITION-BY-FORMULA')
        self.__bindingTime = None

        self.__mixedtext = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__bindingTime = self._read_xml_attribute('BINDING-TIME', BindingTimeEnum.get)

        self.__mixedtext = node.text
        return self

    def get_bindingTime(self) -> BindingTimeEnum:
        return self.__bindingTime

    def set_bindingTime(self, value: BindingTimeEnum) -> None:
        self.__bindingTime = value
        XDT.mark_attribute_dirty('bindingTime', self)

    def get(self) -> str:
        return self.__mixedtext

    def set(self, text: str) -> None:
        self.__mixedtext = text
        if text is not None:
            self._node.text = str(text)
        else:
            self._node.text = ''
        XDT.mark_attribute_dirty('mixedtext', self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['BindingTime'] = self.__bindingTime
        property_values['Value'] = self.__mixedtext
        return property_values


    def _save_contents(self):
        """
        Saves the content of ConditionByFormula node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_SwSystemconstDependentFormula()
        self._save_xml_attribute('BINDING-TIME', 'bindingTime', self.__bindingTime.literal if self.__bindingTime is not None else None)

