class SwSystemconstantValueSet(ARElement):
    """
    This meta-class represents the ability to specify a set of system constant values.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SW-SYSTEMCONSTANT-VALUE-SET'
        self._node = etree.Element('SW-SYSTEMCONSTANT-VALUE-SET')
        self.__swSystemconstantValues = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__swSystemconstantValues, '{*}SW-SYSTEMCONSTANT-VALUES/*', SwSystemconstValue, file, 'swSystemconstantValues', refCounter)
        return self

    def get_swSystemconstantValues(self) -> list[SwSystemconstValue]:
        return list(self.__swSystemconstantValues.keys())

    def __bind_swSystemconstantValue(self, value: SwSystemconstValue) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__swSystemconstantValues.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, SwSystemconstValue) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwSystemconstValue or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'SwSystemconstValue_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_swSystemconstantValue_at_index(self, index: int, value: SwSystemconstValue) -> None:
        """
        Adds a single value to the swSystemconstantValues at the given index
        """
        if value is not None:
            self.__bind_swSystemconstantValue(value)
            AutosarNode._insert_at_index(self.__swSystemconstantValues, value, index)
            self._sync_add_to_merge_target(value)

    def add_swSystemconstantValue(self, value: SwSystemconstValue) -> None:
        """
        Adds a single value to the swSystemconstantValues
        """
        if value is not None:
            self.__bind_swSystemconstantValue(value)
            self.__swSystemconstantValues[value] = None
            self._sync_add_to_merge_target(value)

    def set_swSystemconstantValues(self, values: list[SwSystemconstValue]) -> None:
        """
        Adds a list of ref value to the swSystemconstantValues
        """
        for value in values:
            self.add_swSystemconstantValue(value)

    def remove_swSystemconstantValue(self, value: SwSystemconstValue) -> None:
        """
        Removes a single value from swSystemconstantValues
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_swSystemconstantValues(self, values: list[SwSystemconstValue]) -> None:
        """
        Removes a list of value from swSystemconstantValues
        """
        for value in values:
            self.remove_swSystemconstantValue(value)

    def new_SwSystemconstantValue(self, name: str=None) -> SwSystemconstValue:
        """
        Creates a new SwSystemconstValue under the SwSystemconstantValueSet.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        SwSystemconstValue_obj = SwSystemconstValue()
        if isinstance(SwSystemconstValue_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        SwSystemconstValue_obj.name = name if isinstance(SwSystemconstValue_obj, Referrable) else None
        self.add_swSystemconstantValue(SwSystemconstValue_obj)
        if isinstance(SwSystemconstValue_obj, Referrable):
            SwSystemconstValue_obj.set_shortName(name)
        return SwSystemconstValue_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__swSystemconstantValues)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__swSystemconstantValues:
            return 'swSystemconstantValues'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'swSystemconstantValues':
            self.__swSystemconstantValues[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'swSystemconstantValues':
            self.__swSystemconstantValues.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of SwSystemconstantValueSet node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARElement()
        self._save_child_collection('SW-SYSTEMCONSTANT-VALUES', None, self.__swSystemconstantValues, self._insert_after_tags + ['VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME', 'T', 'S'])

class SwSystemconstValue(ARObject):
    """
    This meta-class assigns a particular value to a system constant.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SW-SYSTEMCONST-VALUE'
        self._node = etree.Element('SW-SYSTEMCONST-VALUE')
        self.__swSystemconst = None
        self.__value = None
        self.__annotations = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        self.__value = self._build_single_child('{*}VALUE', NumericalValueVariationPoint, file, 'value')
        refCounter = self._build_child_collection(self.__annotations, '{*}ANNOTATIONS/*', Annotation, file, 'annotations', refCounter)
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__swSystemconst = self._resolve_single_reference('{*}SW-SYSTEMCONST-REF', self.__swSystemconst)

    def get_swSystemconst(self) -> SwSystemconst:
        return self.__swSystemconst

    def set_swSystemconst(self, value: SwSystemconst) -> None:
        """
        Adds a single value to the swSystemconst
        """
        if value is not None:
            if isinstance(value, SwSystemconst) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwSystemconst or its sub-classes'.format(value))
            if self.__swSystemconst is not None and self.__swSystemconst.is_proxy() is False:
                self.__swSystemconst.referenced_by.remove(self)
            self.__swSystemconst = value
            value.referenced_by.add(self)
        elif self.__swSystemconst is not None:
            if self.__swSystemconst.is_proxy() is False:
                self.__swSystemconst.referenced_by.remove(self)
            self.__swSystemconst = None
        XDT.mark_dirty(self.__swSystemconst, self)

    def get_value(self) -> NumericalValueVariationPoint:
        return self.__value

    def set_value(self, value: NumericalValueVariationPoint) -> None:
        """
        Adds a single value to the value
        """
        if value is not None:
            if isinstance(value, NumericalValueVariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NumericalValueVariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__value = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'NumericalValueVariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__value is not None:
            self.__value._detach_from_parent()
            self.__value = None
        XDT.mark_dirty(self.__value, self)

    def get_annotations(self) -> list[Annotation]:
        return list(self.__annotations.keys())

    def __bind_annotation(self, value: Annotation) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__annotations.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, Annotation) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Annotation or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'Annotation_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['annotationOrigin', 'timestamp', 'checksum'])

    def add_annotation_at_index(self, index: int, value: Annotation) -> None:
        """
        Adds a single value to the annotations at the given index
        """
        if value is not None:
            self.__bind_annotation(value)
            AutosarNode._insert_at_index(self.__annotations, value, index)
            self._sync_add_to_merge_target(value)

    def add_annotation(self, value: Annotation) -> None:
        """
        Adds a single value to the annotations
        """
        if value is not None:
            self.__bind_annotation(value)
            self.__annotations[value] = None
            self._sync_add_to_merge_target(value)

    def set_annotations(self, values: list[Annotation]) -> None:
        """
        Adds a list of ref value to the annotations
        """
        for value in values:
            self.add_annotation(value)

    def remove_annotation(self, value: Annotation) -> None:
        """
        Removes a single value from annotations
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_annotations(self, values: list[Annotation]) -> None:
        """
        Removes a list of value from annotations
        """
        for value in values:
            self.remove_annotation(value)

    def new_Value(self, name: str=None) -> NumericalValueVariationPoint:
        """
        Creates a new NumericalValueVariationPoint under the SwSystemconstValue.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        NumericalValueVariationPoint_obj = NumericalValueVariationPoint()
        if isinstance(NumericalValueVariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        NumericalValueVariationPoint_obj.name = name if isinstance(NumericalValueVariationPoint_obj, Referrable) else None
        self.set_value(NumericalValueVariationPoint_obj)
        if isinstance(NumericalValueVariationPoint_obj, Referrable):
            NumericalValueVariationPoint_obj.set_shortName(name)
        return NumericalValueVariationPoint_obj

    def new_Annotation(self, name: str=None) -> Annotation:
        """
        Creates a new Annotation under the SwSystemconstValue.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Annotation_obj = Annotation()
        if isinstance(Annotation_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        Annotation_obj.name = name if isinstance(Annotation_obj, Referrable) else None
        self.add_annotation(Annotation_obj)
        if isinstance(Annotation_obj, Referrable):
            Annotation_obj.set_shortName(name)
        return Annotation_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__value is not None:
            children.append(self.__value)
        children.extend(self.__annotations)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__value is child:
            return 'value'
        if child in self.__annotations:
            return 'annotations'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'value':
            if self.__value is None:
                self.__value = child
        elif containment_slot == 'annotations':
            self.__annotations[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'value':
            if self.__value is child:
                self.__value = None
        elif containment_slot == 'annotations':
            self.__annotations.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['SwSystemconst'] = self.__swSystemconst
        return property_values


    def _save_contents(self):
        """
        Saves the content of SwSystemconstValue node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_single_reference('SW-SYSTEMCONST-REF', self.__swSystemconst, self._insert_after_tags + ['T', 'S'])
        self._save_single_child('VALUE', self.__value, self._insert_after_tags + ['SW-SYSTEMCONST-REF', 'T', 'S'])
        self._save_child_collection('ANNOTATIONS', None, self.__annotations, self._insert_after_tags + ['VALUE', 'SW-SYSTEMCONST-REF', 'T', 'S'])

