        self._save_child_collection(None, 'BR', self.__brs, self._insert_after_tags + ['TT', 'T', 'S'])
        self._save_child_collection(None, 'XREF', self.__xrefs, self._insert_after_tags + ['BR', 'TT', 'T', 'S'])
        self._save_child_collection(None, 'XREF-TARGET', self.__xrefTargets, self._insert_after_tags + ['XREF', 'BR', 'TT', 'T', 'S'])
