    def new_Formula(self, name: str=None) -> MlFormula:
        """
        Creates a new MlFormula under the DocumentationBlock.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        MlFormula_obj = MlFormula()
        if isinstance(MlFormula_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        MlFormula_obj.name = name if isinstance(MlFormula_obj, Referrable) else None
