class Map(ARObject):
    """
    Image maps enable authors to specify regions of an image or object and assign a specific action to each region (e.g., retrieve a document, run a program, etc.) When the region is activated by the user, the action is executed., , The class follows the html approach and is intended to support interactive documents.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'MAP'
        self._node = etree.Element('MAP')
        self.__class = None
        self.__name = None
        self.__onclick = None
        self.__ondblclick = None
        self.__onkeydown = None
        self.__onkeypress = None
        self.__onkeyup = None
        self.__onmousedown = None
        self.__onmousemove = None
        self.__onmouseout = None
        self.__onmouseover = None
        self.__onmouseup = None
        self.__style = None
        self.__title = None
        self.__areas = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__class = self._read_xml_attribute('CLASS', datatype_utils.get_string_value)
        self.__name = self._read_xml_attribute('NAME', datatype_utils.get_string_value)
        self.__onclick = self._read_xml_attribute('ONCLICK', datatype_utils.get_string_value)
        self.__ondblclick = self._read_xml_attribute('ONDBLCLICK', datatype_utils.get_string_value)
        self.__onkeydown = self._read_xml_attribute('ONKEYDOWN', datatype_utils.get_string_value)
        self.__onkeypress = self._read_xml_attribute('ONKEYPRESS', datatype_utils.get_string_value)
        self.__onkeyup = self._read_xml_attribute('ONKEYUP', datatype_utils.get_string_value)
        self.__onmousedown = self._read_xml_attribute('ONMOUSEDOWN', datatype_utils.get_string_value)
        self.__onmousemove = self._read_xml_attribute('ONMOUSEMOVE', datatype_utils.get_string_value)
        self.__onmouseout = self._read_xml_attribute('ONMOUSEOUT', datatype_utils.get_string_value)
        self.__onmouseover = self._read_xml_attribute('ONMOUSEOVER', datatype_utils.get_string_value)
        self.__onmouseup = self._read_xml_attribute('ONMOUSEUP', datatype_utils.get_string_value)
