        self._save_xml_attribute('NAME', 'name', str(self.__name) if self.__name is not None else None)
        self._save_xml_attribute('ONCLICK', 'onclick', str(self.__onclick) if self.__onclick is not None else None)
        self._save_xml_attribute('ONDBLCLICK', 'ondblclick', str(self.__ondblclick) if self.__ondblclick is not None else None)
        self._save_xml_attribute('ONKEYDOWN', 'onkeydown', str(self.__onkeydown) if self.__onkeydown is not None else None)
        self._save_xml_attribute('ONKEYPRESS', 'onkeypress', str(self.__onkeypress) if self.__onkeypress is not None else None)
        self._save_xml_attribute('ONKEYUP', 'onkeyup', str(self.__onkeyup) if self.__onkeyup is not None else None)
        self._save_xml_attribute('ONMOUSEDOWN', 'onmousedown', str(self.__onmousedown) if self.__onmousedown is not None else None)
        self._save_xml_attribute('ONMOUSEMOVE', 'onmousemove', str(self.__onmousemove) if self.__onmousemove is not None else None)
        self._save_xml_attribute('ONMOUSEOUT', 'onmouseout', str(self.__onmouseout) if self.__onmouseout is not None else None)
