class TraceReferrable(MultilanguageReferrable):
    """
    This meta class is intended to add the category to the subclasses of Traceable. , , Even if the model seems to be a bit awkward, it ensures backwards compatibility of the schema., , This approach allows to have sublclasses of Traceable which are either Identifiable or only Referrable while still maintaining the consistent sequence of shortName, longName, category.
    """
    def __init__(self):
        super().__init__()
        self.__category = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__category = self._read_scalar_element('CATEGORY', datatype_utils.get_string_value)

        return self

    def get_category(self) -> str:
        return self.__category

    def set_category(self, value: str) -> None:
        self.__category = value
        XDT.mark_attribute_dirty('category', self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Category'] = self.__category
        return property_values


    def _save_TraceReferrable(self):
        """
        Saves the content of TraceReferrable node
        """
        super()._save_MultilanguageReferrable()
        self._save_scalar_element('CATEGORY', 'category', str(self.__category) if self.__category is not None else None, create_after_nodes = ['LONG-NAME', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)

class Traceable(MultilanguageReferrable):
    """
    This meta class represents the ability to be subject to tracing within an AUTOSAR model., , Note that it is expected that its subclasses inherit either from MultilanguageReferrable or from Identifiable. Nevertheless it also inherits from MultilanguageReferrable in order to provide a common reference target for all Traceables.
    """
    def __init__(self):
        super().__init__()
        self.__traces = {}


    def _resolve_references(self):
        super()._resolve_references()
        self.__traces = self._resolve_reference_list('{*}TRACE-REFS/*', self.__traces)

    def get_traces(self) -> list[Traceable]:
        return list(self.__traces.keys())

    def __bind_trace(self, value: Traceable) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__traces.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, Traceable) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Traceable or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_trace(self, value: Traceable) -> None:
        """
        Adds a single value to the traces
        """
        if value is not None:
            self.__bind_trace(value)
            self.__traces[value] = None

    def set_traces(self, values: list[Traceable]) -> None:
        """
        Adds a list of ref value to the traces
        """
        for value in values:
            self.add_trace(value)

    def remove_trace(self, value: Traceable) -> None:
        """
        Removes a single value from traces
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__traces.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_traces(self, values: list[Traceable]) -> None:
        """
        Removes a list of value from traces
        """
        for value in values:
            self.remove_trace(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Traces'] = self.__traces
        return property_values


    def _save_Traceable(self):
        """
        Saves the content of Traceable node
        """
        super()._save_MultilanguageReferrable()
        self._save_reference_list('TRACE-REFS', 'TRACE-REF', self.__traces, self._insert_after_tags + ['LONG-NAME', 'SHORT-NAME', 'T', 'S'])

