class Prms(Paginateable):
    """
    This metaclass represents the ability to specify a parameter table. It can be used e.g. to specify parameter tables in a data sheet.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PRMS'
        self._node = etree.Element('PRMS')
        self.__label = None
        self.__prms = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        self.__label = self._build_single_child('{*}LABEL', MultilanguageLongName, file, 'label')
        refCounter = self._build_child_collection(self.__prms, '{*}PRM', GeneralParameter, file, 'prms', refCounter)
        return self

    def get_label(self) -> MultilanguageLongName:
        return self.__label

    def set_label(self, value: MultilanguageLongName) -> None:
        """
        Adds a single value to the label
        """
        if value is not None:
            if isinstance(value, MultilanguageLongName) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of MultilanguageLongName or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__label = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'MultilanguageLongName_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__label is not None:
            self.__label._detach_from_parent()
            self.__label = None
        XDT.mark_dirty(self.__label, self)

    def get_prms(self) -> list[GeneralParameter]:
        return list(self.__prms.keys())

    def __bind_prm(self, value: GeneralParameter) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__prms.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, GeneralParameter) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of GeneralParameter or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'GeneralParameter_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_prm_at_index(self, index: int, value: GeneralParameter) -> None:
        """
        Adds a single value to the prms at the given index
        """
        if value is not None:
            self.__bind_prm(value)
            AutosarNode._insert_at_index(self.__prms, value, index)
            self._sync_add_to_merge_target(value)

    def add_prm(self, value: GeneralParameter) -> None:
        """
        Adds a single value to the prms
        """
        if value is not None:
            self.__bind_prm(value)
            self.__prms[value] = None
            self._sync_add_to_merge_target(value)

    def set_prms(self, values: list[GeneralParameter]) -> None:
        """
        Adds a list of ref value to the prms
        """
        for value in values:
            self.add_prm(value)

    def remove_prm(self, value: GeneralParameter) -> None:
        """
        Removes a single value from prms
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_prms(self, values: list[GeneralParameter]) -> None:
        """
        Removes a list of value from prms
        """
        for value in values:
            self.remove_prm(value)

