class LabeledList(Paginateable):
    """
    This meta-class represents a labeled list, in which items have a label and a content. The policy how to render such items is specified in the labeled list.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'LABELED-LIST'
        self._node = etree.Element('LABELED-LIST')
        self.__indentSample = None
        self.__labeledItems = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        self.__indentSample = self._build_single_child('{*}INDENT-SAMPLE', IndentSample, file, 'indentSample')
        refCounter = self._build_child_collection(self.__labeledItems, '{*}LABELED-ITEM', LabeledItem, file, 'labeledItems', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

