        self._save_child_collection(None, 'FIGURE', self.__figures, self._insert_after_tags + ['DEF-LIST', 'LABEL', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
        self._save_child_collection(None, 'FORMULA', self.__formulas, self._insert_after_tags + ['FIGURE', 'DEF-LIST', 'LABEL', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
        self._save_child_collection(None, 'LABELED-LIST', self.__labeledLists, self._insert_after_tags + ['FORMULA', 'FIGURE', 'DEF-LIST', 'LABEL', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
        self._save_child_collection(None, 'LIST', self.__lists, self._insert_after_tags + ['LABELED-LIST', 'FORMULA', 'FIGURE', 'DEF-LIST', 'LABEL', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
        self._save_child_collection(None, 'NOTE', self.__notes, self._insert_after_tags + ['LIST', 'LABELED-LIST', 'FORMULA', 'FIGURE', 'DEF-LIST', 'LABEL', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
        self._save_child_collection(None, 'P', self.__ps, self._insert_after_tags + ['NOTE', 'LIST', 'LABELED-LIST', 'FORMULA', 'FIGURE', 'DEF-LIST', 'LABEL', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
        self._save_child_collection(None, 'STRUCTURED-REQ', self.__structuredReqs, self._insert_after_tags + ['P', 'NOTE', 'LIST', 'LABELED-LIST', 'FORMULA', 'FIGURE', 'DEF-LIST', 'LABEL', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
        self._save_child_collection(None, 'TRACE', self.__traces, self._insert_after_tags + ['STRUCTURED-REQ', 'P', 'NOTE', 'LIST', 'LABELED-LIST', 'FORMULA', 'FIGURE', 'DEF-LIST', 'LABEL', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
