        self._save_child_collection(None, 'SD', self.__sds, self._insert_after_tags + ['SDG-CAPTION-REF', 'SDG-CAPTION', 'T', 'S'])
        self._save_child_collection(None, 'SDG', self.__sdgs, self._insert_after_tags + ['SD', 'SDG-CAPTION-REF', 'SDG-CAPTION', 'T', 'S'])
