class Code(Identifiable):
    """
    A generic code descriptor. The type of the code (source or object) is defined via the category attribute of the associated engineering object.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CODE'
        self._node = etree.Element('CODE')
        self.__artifactDescriptors = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__artifactDescriptors, '{*}ARTIFACT-DESCRIPTORS/*', AutosarEngineeringObject, file, 'artifactDescriptors', refCounter)
        return self

    def get_artifactDescriptors(self) -> list[AutosarEngineeringObject]:
        return list(self.__artifactDescriptors.keys())

    def __bind_artifactDescriptor(self, value: AutosarEngineeringObject) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__artifactDescriptors.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, AutosarEngineeringObject) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AutosarEngineeringObject or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'AutosarEngineeringObject_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['domain', 'revisionLabels', 'category', 'shortLabel', 'timestamp', 'checksum'])

    def add_artifactDescriptor_at_index(self, index: int, value: AutosarEngineeringObject) -> None:
        """
        Adds a single value to the artifactDescriptors at the given index
        """
        if value is not None:
            self.__bind_artifactDescriptor(value)
            AutosarNode._insert_at_index(self.__artifactDescriptors, value, index)
            self._sync_add_to_merge_target(value)

    def add_artifactDescriptor(self, value: AutosarEngineeringObject) -> None:
        """
        Adds a single value to the artifactDescriptors
        """
        if value is not None:
            self.__bind_artifactDescriptor(value)
            self.__artifactDescriptors[value] = None
            self._sync_add_to_merge_target(value)

    def set_artifactDescriptors(self, values: list[AutosarEngineeringObject]) -> None:
        """
        Adds a list of ref value to the artifactDescriptors
        """
        for value in values:
            self.add_artifactDescriptor(value)

    def remove_artifactDescriptor(self, value: AutosarEngineeringObject) -> None:
        """
        Removes a single value from artifactDescriptors
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
