        refCounter = 0
        refCounter = self._build_child_collection(self.__arTypedPerInstanceMemories, '{*}AR-TYPED-PER-INSTANCE-MEMORYS/*', VariableDataPrototype, file, 'arTypedPerInstanceMemories', refCounter)
