class RunnableEntity(AtpStructureElement,ExecutableEntity):
    """
    A RunnableEntity represents the smallest code-fragment that is provided by an AtomicSwComponentType and are executed under control of the RTE. RunnableEntities are for instance set up to respond to data reception or operation invocation on a server.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RUNNABLE-ENTITY'
        self._node = etree.Element('RUNNABLE-ENTITY')
        self.__canBeInvokedConcurrently = None
        self.__symbol = None
        self.__arguments = {}
        self.__asynchronousServerCallResultPoints = {}
        self.__dataReadAccess = {}
        self.__dataReceivePointByArguments = {}
        self.__dataReceivePointByValues = {}
        self.__dataSendPoints = {}
        self.__dataWriteAccess = {}
        self.__externalTriggeringPoints = {}
        self.__internalTriggeringPoints = {}
        self.__modeAccessPoints = {}
        self.__modeSwitchPoints = {}
        self.__parameterAccess = {}
        self.__readLocalVariables = {}
        self.__serverCallPoints = {}
        self.__waitPoints = {}
        self.__writtenLocalVariables = {}
        self.__variationPoint = None
        self.__serverCallPoints_childTypes = {'ASYNCHRONOUS-SERVER-CALL-POINT': 'AsynchronousServerCallPoint', 'SYNCHRONOUS-SERVER-CALL-POINT': 'SynchronousServerCallPoint', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__canBeInvokedConcurrently = self._read_scalar_element('CAN-BE-INVOKED-CONCURRENTLY', datatype_utils.get_bool_value)
        self.__symbol = self._read_scalar_element('SYMBOL', datatype_utils.get_string_value)

        refCounter = 0
        refCounter = self._build_child_collection(self.__arguments, '{*}ARGUMENTS/*', RunnableEntityArgument, file, 'arguments', refCounter)
        refCounter = self._build_child_collection(self.__asynchronousServerCallResultPoints, '{*}ASYNCHRONOUS-SERVER-CALL-RESULT-POINTS/*', AsynchronousServerCallResultPoint, file, 'asynchronousServerCallResultPoints', refCounter)
        refCounter = self._build_child_collection(self.__dataReadAccess, '{*}DATA-READ-ACCESSS/*', VariableAccess, file, 'dataReadAccess', refCounter)
        refCounter = self._build_child_collection(self.__dataReceivePointByArguments, '{*}DATA-RECEIVE-POINT-BY-ARGUMENTS/*', VariableAccess, file, 'dataReceivePointByArguments', refCounter)
        refCounter = self._build_child_collection(self.__dataReceivePointByValues, '{*}DATA-RECEIVE-POINT-BY-VALUES/*', VariableAccess, file, 'dataReceivePointByValues', refCounter)
        refCounter = self._build_child_collection(self.__dataSendPoints, '{*}DATA-SEND-POINTS/*', VariableAccess, file, 'dataSendPoints', refCounter)
        refCounter = self._build_child_collection(self.__dataWriteAccess, '{*}DATA-WRITE-ACCESSS/*', VariableAccess, file, 'dataWriteAccess', refCounter)
        refCounter = self._build_child_collection(self.__externalTriggeringPoints, '{*}EXTERNAL-TRIGGERING-POINTS/*', ExternalTriggeringPoint, file, 'externalTriggeringPoints', refCounter)
        refCounter = self._build_child_collection(self.__internalTriggeringPoints, '{*}INTERNAL-TRIGGERING-POINTS/*', InternalTriggeringPoint, file, 'internalTriggeringPoints', refCounter)
        refCounter = self._build_child_collection(self.__modeAccessPoints, '{*}MODE-ACCESS-POINTS/*', ModeAccessPoint, file, 'modeAccessPoints', refCounter)
        refCounter = self._build_child_collection(self.__modeSwitchPoints, '{*}MODE-SWITCH-POINTS/*', ModeSwitchPoint, file, 'modeSwitchPoints', refCounter)
