class CompositionSwComponentType(SwComponentType):
    """
    A CompositionSwComponentType aggregates SwComponentPrototypes (that in turn are typed by SwComponentTypes) as well as SwConnectors for primarily connecting SwComponentPrototypes among each others and towards the surface of the CompositionSwComponentType. By this means hierarchical structures of software-components can be created.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'COMPOSITION-SW-COMPONENT-TYPE'
        self._node = etree.Element('COMPOSITION-SW-COMPONENT-TYPE')
        self.__components = {}
        self.__connectors = {}
        self.__constantValueMappings = {}
        self.__dataTypeMappings = {}
        self.__connectors_childTypes = {'ASSEMBLY-SW-CONNECTOR': 'AssemblySwConnector', 'DELEGATION-SW-CONNECTOR': 'DelegationSwConnector', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__components, '{*}COMPONENTS/*', SwComponentPrototype, file, 'components', refCounter)
        refCounter = self._build_child_collection(self.__connectors, '{*}CONNECTORS/*', self.__connectors_childTypes, file, 'connectors', refCounter)
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__constantValueMappings = self._resolve_reference_list('{*}CONSTANT-VALUE-MAPPING-REFS/*', self.__constantValueMappings)
        self.__dataTypeMappings = self._resolve_reference_list('{*}DATA-TYPE-MAPPING-REFS/*', self.__dataTypeMappings)

    def get_components(self) -> list[SwComponentPrototype]:
        return list(self.__components.keys())

    def __bind_component(self, value: SwComponentPrototype) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__components.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, SwComponentPrototype) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwComponentPrototype or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'SwComponentPrototype_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_component_at_index(self, index: int, value: SwComponentPrototype) -> None:
        """
        Adds a single value to the components at the given index
        """
        if value is not None:
            self.__bind_component(value)
            AutosarNode._insert_at_index(self.__components, value, index)
            self._sync_add_to_merge_target(value)

    def add_component(self, value: SwComponentPrototype) -> None:
        """
        Adds a single value to the components
        """
        if value is not None:
            self.__bind_component(value)
            self.__components[value] = None
            self._sync_add_to_merge_target(value)

    def set_components(self, values: list[SwComponentPrototype]) -> None:
        """
        Adds a list of ref value to the components
        """
        for value in values:
            self.add_component(value)

    def remove_component(self, value: SwComponentPrototype) -> None:
        """
        Removes a single value from components
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_components(self, values: list[SwComponentPrototype]) -> None:
        """
        Removes a list of value from components
        """
        for value in values:
            self.remove_component(value)

    def get_connectors(self) -> list[SwConnector]:
        return list(self.__connectors.keys())

    def __bind_connector(self, value: SwConnector) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__connectors.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, SwConnector) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwConnector or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'SwConnector_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_connector_at_index(self, index: int, value: SwConnector) -> None:
        """
        Adds a single value to the connectors at the given index
        """
        if value is not None:
            self.__bind_connector(value)
            AutosarNode._insert_at_index(self.__connectors, value, index)
            self._sync_add_to_merge_target(value)

    def add_connector(self, value: SwConnector) -> None:
        """
        Adds a single value to the connectors
        """
        if value is not None:
            self.__bind_connector(value)
            self.__connectors[value] = None
            self._sync_add_to_merge_target(value)

    def set_connectors(self, values: list[SwConnector]) -> None:
        """
        Adds a list of ref value to the connectors
        """
        for value in values:
            self.add_connector(value)

    def remove_connector(self, value: SwConnector) -> None:
        """
        Removes a single value from connectors
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_connectors(self, values: list[SwConnector]) -> None:
        """
        Removes a list of value from connectors
        """
        for value in values:
            self.remove_connector(value)

    def get_constantValueMappings(self) -> list[ConstantSpecificationMappingSet]:
        return list(self.__constantValueMappings.keys())

    def __bind_constantValueMapping(self, value: ConstantSpecificationMappingSet) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__constantValueMappings.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, ConstantSpecificationMappingSet) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ConstantSpecificationMappingSet or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_constantValueMapping(self, value: ConstantSpecificationMappingSet) -> None:
        """
        Adds a single value to the constantValueMappings
        """
        if value is not None:
            self.__bind_constantValueMapping(value)
            self.__constantValueMappings[value] = None

    def set_constantValueMappings(self, values: list[ConstantSpecificationMappingSet]) -> None:
        """
        Adds a list of ref value to the constantValueMappings
        """
