class InvalidationPolicy(ARObject):
    """
    Specifies whether the component can actively invalidate a particular dataElement., , If no invalidationPolicy points to a dataElement this is considered to yield the identical result as if the handleInvalid attribute was set to dontInvalidate.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'INVALIDATION-POLICY'
        self._node = etree.Element('INVALIDATION-POLICY')
        self.__handleInvalid = None
        self.__dataElement = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__handleInvalid = self._read_scalar_element('HANDLE-INVALID', HandleInvalidEnum.get)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__dataElement = self._resolve_single_reference('{*}DATA-ELEMENT-REF', self.__dataElement)

    def get_handleInvalid(self) -> HandleInvalidEnum:
        return self.__handleInvalid

    def set_handleInvalid(self, value: HandleInvalidEnum) -> None:
        self.__handleInvalid = value
        XDT.mark_attribute_dirty('handleInvalid', self)

    def get_dataElement(self) -> VariableDataPrototype:
        return self.__dataElement

    def set_dataElement(self, value: VariableDataPrototype) -> None:
        """
        Adds a single value to the dataElement
        """
        if value is not None:
            if isinstance(value, VariableDataPrototype) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariableDataPrototype or its sub-classes'.format(value))
            if self.__dataElement is not None and self.__dataElement.is_proxy() is False:
                self.__dataElement.referenced_by.remove(self)
            self.__dataElement = value
            value.referenced_by.add(self)
        elif self.__dataElement is not None:
            if self.__dataElement.is_proxy() is False:
                self.__dataElement.referenced_by.remove(self)
            self.__dataElement = None
        XDT.mark_dirty(self.__dataElement, self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['HandleInvalid'] = self.__handleInvalid
        property_values['DataElement'] = self.__dataElement
        return property_values


    def _save_contents(self):
        """
        Saves the content of InvalidationPolicy node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_single_reference('DATA-ELEMENT-REF', self.__dataElement, self._insert_after_tags + ['T', 'S'])
        self._save_scalar_element('HANDLE-INVALID', 'handleInvalid', self.__handleInvalid.literal if self.__handleInvalid is not None else None, create_after_nodes = ['DATA-ELEMENT-REF', 'T', 'S'] + self._insert_after_tags)

