class SystemMapping(Identifiable):
    """
    The system mapping aggregates all mapping aspects (mapping of SW components to ECUs, mapping of data elements to signals, and mapping constraints).
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SYSTEM-MAPPING'
        self._node = etree.Element('SYSTEM-MAPPING')
        self.__dataMappings = {}
        self.__ecuResourceMappings = {}
        self.__mappingConstraints = {}
        self.__pncMappings = {}
        self.__resourceEstimations = {}
        self.__signalPathConstraints = {}
        self.__swImplMappings = {}
        self.__swMappings = {}
        self.__variationPoint = None
        self.__dataMappings_childTypes = {'CLIENT-SERVER-TO-SIGNAL-GROUP-MAPPING': 'ClientServerToSignalGroupMapping', 'SENDER-RECEIVER-TO-SIGNAL-GROUP-MAPPING': 'SenderReceiverToSignalGroupMapping', 'SENDER-RECEIVER-TO-SIGNAL-MAPPING': 'SenderReceiverToSignalMapping', }
        self.__mappingConstraints_childTypes = {'COMPONENT-CLUSTERING': 'ComponentClustering', 'COMPONENT-SEPARATION': 'ComponentSeparation', 'SWC-TO-ECU-MAPPING-CONSTRAINT': 'SwcToEcuMappingConstraint', }
        self.__signalPathConstraints_childTypes = {'COMMON-SIGNAL-PATH': 'CommonSignalPath', 'FORBIDDEN-SIGNAL-PATH': 'ForbiddenSignalPath', 'PERMISSIBLE-SIGNAL-PATH': 'PermissibleSignalPath', 'SEPARATE-SIGNAL-PATH': 'SeparateSignalPath', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__dataMappings, '{*}DATA-MAPPINGS/*', self.__dataMappings_childTypes, file, 'dataMappings', refCounter)
        refCounter = self._build_child_collection(self.__ecuResourceMappings, '{*}ECU-RESOURCE-MAPPINGS/*', ECUMapping, file, 'ecuResourceMappings', refCounter)
        refCounter = self._build_child_collection(self.__mappingConstraints, '{*}MAPPING-CONSTRAINTS/*', self.__mappingConstraints_childTypes, file, 'mappingConstraints', refCounter)
        refCounter = self._build_child_collection(self.__pncMappings, '{*}PNC-MAPPINGS/*', PncMapping, file, 'pncMappings', refCounter)
        refCounter = self._build_child_collection(self.__resourceEstimations, '{*}RESOURCE-ESTIMATIONS/*', EcuResourceEstimation, file, 'resourceEstimations', refCounter)
        refCounter = self._build_child_collection(self.__signalPathConstraints, '{*}SIGNAL-PATH-CONSTRAINTS/*', self.__signalPathConstraints_childTypes, file, 'signalPathConstraints', refCounter)
        refCounter = self._build_child_collection(self.__swImplMappings, '{*}SW-IMPL-MAPPINGS/*', SwcToImplMapping, file, 'swImplMappings', refCounter)
        refCounter = self._build_child_collection(self.__swMappings, '{*}SW-MAPPINGS/*', SwcToEcuMapping, file, 'swMappings', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

