class Gateway(FibexElement):
    """
    A gateway is an ECU that is connected to two or more clusters (channels, but not redundant), and performs a frame, Pdu or signal mapping between them.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'GATEWAY'
        self._node = etree.Element('GATEWAY')
        self.__ecu = None
        self.__frameMappings = {}
        self.__iPduMappings = {}
        self.__signalMappings = {}

