class ModeDrivenTransmissionModeCondition(ARObject):
    """
    The condition defined by this class evaluates to true if one of the referenced modeDeclarations (OR associated) is active. All referenced modeDeclarations shall be from the same ModeDeclarationGroup., , The condition is used to define which TransmissionMode shall be activated using Com_SwitchIpduTxMode.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'MODE-DRIVEN-TRANSMISSION-MODE-CONDITION'
        self._node = etree.Element('MODE-DRIVEN-TRANSMISSION-MODE-CONDITION')
        self.__modeDeclarations = {}


    def _resolve_references(self):
        super()._resolve_references()
        self.__modeDeclarations = self._resolve_reference_list('{*}MODE-DECLARATION-REFS/*', self.__modeDeclarations)

    def get_modeDeclarations(self) -> list[ModeDeclaration]:
        return list(self.__modeDeclarations.keys())

    def __bind_modeDeclaration(self, value: ModeDeclaration) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__modeDeclarations.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, ModeDeclaration) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ModeDeclaration or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_modeDeclaration(self, value: ModeDeclaration) -> None:
        """
        Adds a single value to the modeDeclarations
        """
        if value is not None:
            self.__bind_modeDeclaration(value)
            self.__modeDeclarations[value] = None

    def set_modeDeclarations(self, values: list[ModeDeclaration]) -> None:
        """
        Adds a list of ref value to the modeDeclarations
        """
        for value in values:
            self.add_modeDeclaration(value)

    def remove_modeDeclaration(self, value: ModeDeclaration) -> None:
        """
        Removes a single value from modeDeclarations
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__modeDeclarations.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_modeDeclarations(self, values: list[ModeDeclaration]) -> None:
        """
        Removes a list of value from modeDeclarations
        """
        for value in values:
            self.remove_modeDeclaration(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['ModeDeclarations'] = self.__modeDeclarations
        return property_values


    def _save_contents(self):
        """
        Saves the content of ModeDrivenTransmissionModeCondition node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_reference_list('MODE-DECLARATION-REFS', 'MODE-DECLARATION-REF', self.__modeDeclarations, self._insert_after_tags + ['T', 'S'])

