class CanTpNode(Identifiable):
    """
    TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CAN-TP-NODE'
        self._node = etree.Element('CAN-TP-NODE')
        self.__maxFcWait = None
        self.__stMin = None
        self.__timeoutAr = None
        self.__timeoutAs = None
        self.__connector = None
        self.__tpAddress = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__maxFcWait = self._read_scalar_element('MAX-FC-WAIT', datatype_utils.get_int_value)
        self.__stMin = self._read_scalar_element('ST-MIN', datatype_utils.get_float_value)
        self.__timeoutAr = self._read_scalar_element('TIMEOUT-AR', datatype_utils.get_float_value)
        self.__timeoutAs = self._read_scalar_element('TIMEOUT-AS', datatype_utils.get_float_value)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__connector = self._resolve_single_reference('{*}CONNECTOR-REF', self.__connector)
        self.__tpAddress = self._resolve_single_reference('{*}TP-ADDRESS-REF', self.__tpAddress)

