class NmNode(Identifiable):
    """
    The linking of NmEcus to NmClusters is realized via the NmNodes.
    """
    def __init__(self):
        super().__init__()
        self.__nmNodeId = None
        self.__nmPassiveModeEnabled = None
        self.__controller = None
        self.__nmIfEcu = None
        self.__rxNmPdus = {}
        self.__txNmPdus = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__nmNodeId = self._read_scalar_element('NM-NODE-ID', datatype_utils.get_int_value)
        self.__nmPassiveModeEnabled = self._read_scalar_element('NM-PASSIVE-MODE-ENABLED', datatype_utils.get_bool_value)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__controller = self._resolve_single_reference('{*}CONTROLLER-REF', self.__controller)
        self.__nmIfEcu = self._resolve_single_reference('{*}NM-IF-ECU-REF', self.__nmIfEcu)
        self.__rxNmPdus = self._resolve_reference_list('{*}RX-NM-PDU-REFS/*', self.__rxNmPdus)
        self.__txNmPdus = self._resolve_reference_list('{*}TX-NM-PDU-REFS/*', self.__txNmPdus)

    def get_nmNodeId(self) -> int:
        return self.__nmNodeId

    def set_nmNodeId(self, value: int) -> None:
        self.__nmNodeId = value
        XDT.mark_attribute_dirty('nmNodeId', self)

    def get_nmPassiveModeEnabled(self) -> bool:
        return self.__nmPassiveModeEnabled

    def set_nmPassiveModeEnabled(self, value: bool) -> None:
        self.__nmPassiveModeEnabled = value
        XDT.mark_attribute_dirty('nmPassiveModeEnabled', self)

    def get_controller(self) -> CommunicationController:
        return self.__controller

    def set_controller(self, value: CommunicationController) -> None:
        """
        Adds a single value to the controller
        """
        if value is not None:
            if isinstance(value, CommunicationController) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CommunicationController or its sub-classes'.format(value))
            if self.__controller is not None and self.__controller.is_proxy() is False:
                self.__controller.referenced_by.remove(self)
            self.__controller = value
            value.referenced_by.add(self)
        elif self.__controller is not None:
            if self.__controller.is_proxy() is False:
                self.__controller.referenced_by.remove(self)
            self.__controller = None
        XDT.mark_dirty(self.__controller, self)

    def get_nmIfEcu(self) -> NmEcu:
        return self.__nmIfEcu

    def set_nmIfEcu(self, value: NmEcu) -> None:
        """
        Adds a single value to the nmIfEcu
        """
        if value is not None:
            if isinstance(value, NmEcu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NmEcu or its sub-classes'.format(value))
            if self.__nmIfEcu is not None and self.__nmIfEcu.is_proxy() is False:
                self.__nmIfEcu.referenced_by.remove(self)
            self.__nmIfEcu = value
            value.referenced_by.add(self)
        elif self.__nmIfEcu is not None:
            if self.__nmIfEcu.is_proxy() is False:
                self.__nmIfEcu.referenced_by.remove(self)
            self.__nmIfEcu = None
        XDT.mark_dirty(self.__nmIfEcu, self)

    def get_rxNmPdus(self) -> list[NmPdu]:
        return list(self.__rxNmPdus.keys())

    def __bind_rxNmPdu(self, value: NmPdu) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__rxNmPdus.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, NmPdu) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NmPdu or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_rxNmPdu(self, value: NmPdu) -> None:
        """
        Adds a single value to the rxNmPdus
        """
        if value is not None:
            self.__bind_rxNmPdu(value)
            self.__rxNmPdus[value] = None

    def set_rxNmPdus(self, values: list[NmPdu]) -> None:
        """
        Adds a list of ref value to the rxNmPdus
        """
        for value in values:
            self.add_rxNmPdu(value)

    def remove_rxNmPdu(self, value: NmPdu) -> None:
        """
        Removes a single value from rxNmPdus
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__rxNmPdus.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_rxNmPdus(self, values: list[NmPdu]) -> None:
        """
        Removes a list of value from rxNmPdus
        """
        for value in values:
            self.remove_rxNmPdu(value)

    def get_txNmPdus(self) -> list[NmPdu]:
        return list(self.__txNmPdus.keys())

    def __bind_txNmPdu(self, value: NmPdu) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__txNmPdus.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, NmPdu) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NmPdu or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_txNmPdu(self, value: NmPdu) -> None:
        """
        Adds a single value to the txNmPdus
        """
        if value is not None:
            self.__bind_txNmPdu(value)
            self.__txNmPdus[value] = None

    def set_txNmPdus(self, values: list[NmPdu]) -> None:
        """
        Adds a list of ref value to the txNmPdus
        """
        for value in values:
            self.add_txNmPdu(value)

    def remove_txNmPdu(self, value: NmPdu) -> None:
        """
        Removes a single value from txNmPdus
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__txNmPdus.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_txNmPdus(self, values: list[NmPdu]) -> None:
        """
        Removes a list of value from txNmPdus
        """
        for value in values:
            self.remove_txNmPdu(value)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the NmNode.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['NmNodeId'] = self.__nmNodeId
        property_values['NmPassiveModeEnabled'] = self.__nmPassiveModeEnabled
        property_values['Controller'] = self.__controller
        property_values['NmIfEcu'] = self.__nmIfEcu
        property_values['RxNmPdus'] = self.__rxNmPdus
        property_values['TxNmPdus'] = self.__txNmPdus
        return property_values


    def _save_NmNode(self):
        """
        Saves the content of NmNode node
        """
        super()._save_Identifiable()
        self._save_single_reference('CONTROLLER-REF', self.__controller, self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME', 'T', 'S'])
        self._save_single_reference('NM-IF-ECU-REF', self.__nmIfEcu, self._insert_after_tags + ['CONTROLLER-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME', 'T', 'S'])
        self._save_scalar_element('NM-NODE-ID', 'nmNodeId', str(self.__nmNodeId) if self.__nmNodeId is not None else None, create_after_nodes = ['NM-IF-ECU-REF', 'CONTROLLER-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
        self._save_scalar_element('NM-PASSIVE-MODE-ENABLED', 'nmPassiveModeEnabled', ('true' if self.__nmPassiveModeEnabled is True else 'false') if self.__nmPassiveModeEnabled is not None else None, create_after_nodes = ['NM-NODE-ID', 'NM-IF-ECU-REF', 'CONTROLLER-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
        self._save_reference_list('RX-NM-PDU-REFS', 'RX-NM-PDU-REF', self.__rxNmPdus, self._insert_after_tags + ['NM-PASSIVE-MODE-ENABLED', 'NM-NODE-ID', 'NM-IF-ECU-REF', 'CONTROLLER-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME', 'T', 'S'])
        self._save_reference_list('TX-NM-PDU-REFS', 'TX-NM-PDU-REF', self.__txNmPdus, self._insert_after_tags + ['RX-NM-PDU-REFS', 'NM-PASSIVE-MODE-ENABLED', 'NM-NODE-ID', 'NM-IF-ECU-REF', 'CONTROLLER-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['TX-NM-PDU-REFS', 'RX-NM-PDU-REFS', 'NM-PASSIVE-MODE-ENABLED', 'NM-NODE-ID', 'NM-IF-ECU-REF', 'CONTROLLER-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME', 'T', 'S'])

