class UdpNmClusterCoupling(NmClusterCoupling):
    """
    Udp attributes that are valid for each of the referenced (coupled) UdpNm clusters.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'UDP-NM-CLUSTER-COUPLING'
        self._node = etree.Element('UDP-NM-CLUSTER-COUPLING')
        self.__nmBusLoadReductionEnabled = None
        self.__nmImmediateRestartEnabled = None
        self.__coupledClusters = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__nmBusLoadReductionEnabled = self._read_scalar_element('NM-BUS-LOAD-REDUCTION-ENABLED', datatype_utils.get_bool_value)
        self.__nmImmediateRestartEnabled = self._read_scalar_element('NM-IMMEDIATE-RESTART-ENABLED', datatype_utils.get_bool_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__coupledClusters = self._resolve_reference_list('{*}COUPLED-CLUSTER-REFS/*', self.__coupledClusters)

    def get_nmBusLoadReductionEnabled(self) -> bool:
        return self.__nmBusLoadReductionEnabled

    def set_nmBusLoadReductionEnabled(self, value: bool) -> None:
        self.__nmBusLoadReductionEnabled = value
        XDT.mark_attribute_dirty('nmBusLoadReductionEnabled', self)

    def get_nmImmediateRestartEnabled(self) -> bool:
        return self.__nmImmediateRestartEnabled

    def set_nmImmediateRestartEnabled(self, value: bool) -> None:
        self.__nmImmediateRestartEnabled = value
        XDT.mark_attribute_dirty('nmImmediateRestartEnabled', self)

    def get_coupledClusters(self) -> list[UdpNmCluster]:
        return list(self.__coupledClusters.keys())

    def __bind_coupledCluster(self, value: UdpNmCluster) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__coupledClusters.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, UdpNmCluster) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of UdpNmCluster or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_coupledCluster(self, value: UdpNmCluster) -> None:
        """
        Adds a single value to the coupledClusters
        """
        if value is not None:
            self.__bind_coupledCluster(value)
            self.__coupledClusters[value] = None

    def set_coupledClusters(self, values: list[UdpNmCluster]) -> None:
        """
        Adds a list of ref value to the coupledClusters
        """
        for value in values:
            self.add_coupledCluster(value)

    def remove_coupledCluster(self, value: UdpNmCluster) -> None:
        """
        Removes a single value from coupledClusters
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__coupledClusters.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_coupledClusters(self, values: list[UdpNmCluster]) -> None:
        """
        Removes a list of value from coupledClusters
        """
        for value in values:
            self.remove_coupledCluster(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['NmBusLoadReductionEnabled'] = self.__nmBusLoadReductionEnabled
        property_values['NmImmediateRestartEnabled'] = self.__nmImmediateRestartEnabled
        property_values['CoupledClusters'] = self.__coupledClusters
        return property_values


    def _save_contents(self):
        """
        Saves the content of UdpNmClusterCoupling node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_NmClusterCoupling()
        self._save_reference_list('COUPLED-CLUSTER-REFS', 'COUPLED-CLUSTER-REF', self.__coupledClusters, self._insert_after_tags + ['T', 'S'])
        self._save_scalar_element('NM-BUS-LOAD-REDUCTION-ENABLED', 'nmBusLoadReductionEnabled', ('true' if self.__nmBusLoadReductionEnabled is True else 'false') if self.__nmBusLoadReductionEnabled is not None else None, create_after_nodes = ['COUPLED-CLUSTER-REFS', 'T', 'S'] + self._insert_after_tags)
        self._save_scalar_element('NM-IMMEDIATE-RESTART-ENABLED', 'nmImmediateRestartEnabled', ('true' if self.__nmImmediateRestartEnabled is True else 'false') if self.__nmImmediateRestartEnabled is not None else None, create_after_nodes = ['NM-BUS-LOAD-REDUCTION-ENABLED', 'COUPLED-CLUSTER-REFS', 'T', 'S'] + self._insert_after_tags)

