class EndToEndProtectionISignalIPdu(ARObject):
    """
    It is possible to protect the inter-ECU data exchange of safety-related ISignalGroups at the level of COM IPdus using protection mechanisms provided by E2E Library. For each ISignalGroup to be protected, a separate EndToEndProtectionISignalIPdu element must be created within the EndToEndProtectionSet. , , The EndToEndProtectionISignalIPdu element refers to the ISignalGroup that is to be protected and to the ISignalIPdu that transmits the protected ISignalGroup. The information how the referenced ISignalGroup shall be protected (through which E2E Profile and with which E2E settings) is defined in the EndToEndDescription element.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'END-TO-END-PROTECTION-I-SIGNAL-I-PDU'
        self._node = etree.Element('END-TO-END-PROTECTION-I-SIGNAL-I-PDU')
        self.__dataOffset = None
        self.__iSignalGroup = None
        self.__iSignalIPdu = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__dataOffset = self._read_scalar_element('DATA-OFFSET', datatype_utils.get_int_value)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__iSignalGroup = self._resolve_single_reference('{*}I-SIGNAL-GROUP-REF', self.__iSignalGroup)
        self.__iSignalIPdu = self._resolve_single_reference('{*}I-SIGNAL-I-PDU-REF', self.__iSignalIPdu)

    def get_dataOffset(self) -> int:
        return self.__dataOffset

    def set_dataOffset(self, value: int) -> None:
        self.__dataOffset = value
        XDT.mark_attribute_dirty('dataOffset', self)

    def get_iSignalGroup(self) -> ISignalGroup:
        return self.__iSignalGroup

    def set_iSignalGroup(self, value: ISignalGroup) -> None:
        """
        Adds a single value to the iSignalGroup
        """
        if value is not None:
            if isinstance(value, ISignalGroup) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ISignalGroup or its sub-classes'.format(value))
            if self.__iSignalGroup is not None and self.__iSignalGroup.is_proxy() is False:
                self.__iSignalGroup.referenced_by.remove(self)
            self.__iSignalGroup = value
            value.referenced_by.add(self)
        elif self.__iSignalGroup is not None:
            if self.__iSignalGroup.is_proxy() is False:
                self.__iSignalGroup.referenced_by.remove(self)
            self.__iSignalGroup = None
        XDT.mark_dirty(self.__iSignalGroup, self)

    def get_iSignalIPdu(self) -> ISignalIPdu:
        return self.__iSignalIPdu

    def set_iSignalIPdu(self, value: ISignalIPdu) -> None:
        """
        Adds a single value to the iSignalIPdu
        """
        if value is not None:
            if isinstance(value, ISignalIPdu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ISignalIPdu or its sub-classes'.format(value))
            if self.__iSignalIPdu is not None and self.__iSignalIPdu.is_proxy() is False:
                self.__iSignalIPdu.referenced_by.remove(self)
            self.__iSignalIPdu = value
            value.referenced_by.add(self)
        elif self.__iSignalIPdu is not None:
            if self.__iSignalIPdu.is_proxy() is False:
                self.__iSignalIPdu.referenced_by.remove(self)
            self.__iSignalIPdu = None
        XDT.mark_dirty(self.__iSignalIPdu, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the EndToEndProtectionISignalIPdu.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['DataOffset'] = self.__dataOffset
        property_values['ISignalGroup'] = self.__iSignalGroup
        property_values['ISignalIPdu'] = self.__iSignalIPdu
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of EndToEndProtectionISignalIPdu node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_scalar_element('DATA-OFFSET', 'dataOffset', str(self.__dataOffset) if self.__dataOffset is not None else None, create_after_nodes = ['T', 'S'] + self._insert_after_tags)
        self._save_single_reference('I-SIGNAL-GROUP-REF', self.__iSignalGroup, self._insert_after_tags + ['DATA-OFFSET', 'T', 'S'])
        self._save_single_reference('I-SIGNAL-I-PDU-REF', self.__iSignalIPdu, self._insert_after_tags + ['I-SIGNAL-GROUP-REF', 'DATA-OFFSET', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['I-SIGNAL-I-PDU-REF', 'I-SIGNAL-GROUP-REF', 'DATA-OFFSET', 'T', 'S'])

