class UnresolvedRef(AutosarNode):
    """Placeholder class for all unresolved references"""
    def __init__(self, path, dest):
        super().__init__()
        self.path = path
        self.autosar_path = path
        self.dest = dest
        self.name = path

    def is_proxy(self) -> bool:
        return True

    def __repr__(self):
        return 'UnresolvedRef(' + str(self.path) + ')'

# Exception classes
class NoShortNameException(Exception):
    """Exception raised when short name is not provided as argument for Referrable objects"""
